<script setup lang="ts">
import{ref,onMounted,onBeforeUnmount}from'vue';import type{Task}from'../../../packages/contracts';import{taskFile,allowFileAccess}from'./task-files';import{t,errorText}from'./i18n';import Icon from'./Icon.vue';
const props=defineProps<{tasks:Task[];action:'convert'|'compress'|'merge'}>(),emit=defineEmits<{close:[];ready:[files:File[]]}>();const dialog=ref<HTMLDialogElement>(),files=ref<(File|undefined)[]>(props.tasks.map(()=>undefined)),loading=ref(false),error=ref('');const abort=new AbortController();
async function resolve(){loading.value=true;try{for(let i=0;i<props.tasks.length;i++)if(!files.value[i])try{files.value[i]=await taskFile(props.tasks[i]!,abort.signal);}catch{/* The chooser below provides explicit disk access without a copy. */}}finally{loading.value=false;}}
function choose(index:number,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(file)files.value[index]=file;}
async function authorize(){try{error.value='';await allowFileAccess();await resolve();}catch(e){error.value=(e as Error).message;}}
onMounted(()=>{dialog.value?.showModal();void resolve();});onBeforeUnmount(()=>abort.abort());
</script>
<template><dialog ref="dialog" class="history-dialog batch-dialog" :aria-label="t('selectedFiles')" @cancel="emit('close')"><h2>{{ t('selectedFiles') }} · {{ tasks.length }}</h2><p>{{ t('batchSequential') }}</p><p v-if="error" class="error" role="alert">{{ error.startsWith('tv') ? t(error) : errorText(error) }}</p><ol class="batch-files"><li v-for="(task,index) in tasks" :key="task.id"><Icon :name="files[index] ? 'check' : 'folder'" /><span dir="auto">{{ files[index]?.name || task.title }}</span><label v-if="!files[index]" class="secondary file-picker">{{ t('chooseVideos') }}<input type="file" accept="video/*,.mkv,.mov,.avi,.ts,.m2ts" :aria-label="t('chooseVideos') + ' · ' + task.title" @change="choose(index,$event)"></label></li></ol><button v-if="files.some(f=>!f)" class="text-button" :disabled="loading" @click="authorize">{{ t('allowLocalFiles') }}</button><div class="dialog-actions"><button class="secondary" @click="emit('close')">{{ t('cancel') }}</button><button class="primary" :disabled="loading || files.some(f=>!f)" @click="emit('ready',files as File[])">{{ t(action + 'Tool') }}</button></div></dialog></template>
<style scoped>.batch-dialog{max-width:740px;width:90vw}.batch-files{padding:0;list-style:none;max-height:55vh;overflow:auto}.batch-files li{display:flex;align-items:center;gap:12px;padding-block:12px;border-block-end:1px solid var(--border);font-size:13px}.batch-files li>span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.batch-files .file-picker{font-size:11px;padding:8px}.batch-dialog p{font-size:13px;color:var(--muted)}</style>
